const i = $input.first().json || {};
const t = String(i.texto || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let op = i.op || 'arquivo';
if (!i.op) { if (/^(sim,?\s*)?importar[.!]*$/.test(t)) op = 'confirmar'; else if (/^nao importar[.!]*$/.test(t)) op = 'cancelar'; }
return [{ json: { op, autor: i.autor || 'Daniel', numero: i.numero, messageId: i.messageId || '', arquivo_nome: String(i.arquivo_nome || 'extrato'), mime: String(i.arquivo_mime || ''), instancia: i.instancia || 'dyno', primeiro: String(i.nome_exibicao || i.autor || '').split(' ')[0] } }];

const p = $('Preparar').first().json;
const r = $input.first().json || {};
const b64 = String(r.base64 || '');
const nome = p.arquivo_nome || 'extrato';
const mime = String(r.mimetype || p.mime || '').toLowerCase();
const ext = (nome.match(/\.([a-z0-9]+)$/i) || [])[1] ? nome.match(/\.([a-z0-9]+)$/i)[1].toLowerCase() : '';
let kind = 'desconhecido';
if (/pdf/.test(mime) || ext === 'pdf') kind = 'pdf';
else if (/sheet|excel/.test(mime) || ext === 'xlsx' || ext === 'xls') kind = 'excel';
else if (/csv|text|ofx|plain/.test(mime) || ['csv', 'ofx', 'txt', 'qfx'].includes(ext)) kind = 'texto';
if (!b64) return [{ json: { kind: 'erro', motivo: 'download' } }];
if (kind === 'excel') return [{ json: { kind, nome }, binary: { data: { data: b64, mimeType: mime || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: nome } } }];
if (kind === 'texto') {
  let txt = Buffer.from(b64, 'base64').toString('utf8');
  if (/�/.test(txt.slice(0, 2000))) txt = Buffer.from(b64, 'base64').toString('latin1');
  return [{ json: { kind, nome, texto: txt.slice(0, 150000) } }];
}
if (kind === 'pdf') return [{ json: { kind, nome, base64: b64 } }];
return [{ json: { kind: 'desconhecido', nome } }];

const linhas = $input.all().map(i => i.json).filter(r => r && typeof r === 'object');
const txt = linhas.slice(0, 3000).map(r => Object.values(r).map(v => String(v == null ? '' : v).replace(/[\r\n;]+/g, ' ')).join(' ; ')).join('\n');
const cab = linhas[0] ? Object.keys(linhas[0]).join(' ; ') : '';
return [{ json: { kind: 'texto', nome: $('Preparar arquivo').first().json.nome, texto: (cab + '\n' + txt).slice(0, 150000) } }];

// Pedido para a camada de IA (tarefa: documento). Quem lê é o provedor de dyno_config.ia_documento (hoje: Claude), com OpenAI de reserva.
let a = null;
try { a = $('Planilha em texto').first().json; } catch (e) { a = null; }
if (!a) a = $('Preparar arquivo').first().json;
const p = $('Preparar').first().json;
const hoje = DateTime.now().setZone('America/Sao_Paulo').toISODate();
const regras = "Você lê extratos de conta bancária e faturas de cartão de crédito brasileiros e devolve TODOS os lançamentos em JSON, sem inventar nada.
Regras:
- data no formato AAAA-MM-DD. Se o ano não aparecer, deduza pelo período do documento. Hoje é HOJE.
- valor sempre positivo (em reais). movimento: despesa (saída, compra, débito, pagamento) ou receita (entrada, crédito, estorno, Pix recebido).
- FATURA DE CARTÃO: cada compra é despesa com forma_pagamento "cartão de crédito". Compra parcelada: lance só a parcela desta fatura e ponha "parcela X/Y" na descrição. IOF, juros, multa e anuidade são despesa (categoria contas). Estornos e créditos são receita (categoria reembolso). "Pagamento recebido"/"pagamento da fatura" tem ignorar=true.
- EXTRATO DE CONTA: Pix enviado, TED, boleto, compra no débito e tarifas são despesa (forma_pagamento: Pix, transferência, boleto ou cartão de débito). Pix recebido, salário e depósitos são receita.
- ignorar=true (com motivo curto) para: linhas de saldo, pagamento de fatura de cartão de crédito (os gastos entram pela fatura), transferências entre contas da própria pessoa, aplicações e resgates de investimento/cofrinho/caixinha, lançamentos cancelados.
- descricao curta e legível (nome do estabelecimento ou da pessoa), sem códigos e sem CPF/CNPJ.
- categoria: despesas em alimentacao, mercado, transporte, combustivel, moradia, contas, saude, lazer, educacao, compras, assinaturas, viagem, trabalho, impostos ou outros; receitas em salario, vendas, freelance, reembolso, investimentos ou outros.
- Se o arquivo não for extrato nem fatura, tipo_documento "outro" e lancamentos vazio.
- Confira no fim: a quantidade de lançamentos devolvidos deve bater com as linhas do documento; não pule páginas.".replace('HOJE', hoje);
const schema = {"type": "object", "additionalProperties": false, "required": ["tipo_documento", "instituicao", "periodo_inicio", "periodo_fim", "lancamentos"], "properties": {"tipo_documento": {"type": "string", "enum": ["extrato_conta", "fatura_cartao", "outro"]}, "instituicao": {"type": ["string", "null"]}, "periodo_inicio": {"type": ["string", "null"]}, "periodo_fim": {"type": ["string", "null"]}, "lancamentos": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["data", "descricao", "valor", "movimento", "categoria", "forma_pagamento", "ignorar", "motivo"], "properties": {"data": {"type": "string"}, "descricao": {"type": "string"}, "valor": {"type": "number"}, "movimento": {"type": "string", "enum": ["despesa", "receita"]}, "categoria": {"type": "string", "enum": ["alimentacao", "mercado", "transporte", "combustivel", "moradia", "contas", "saude", "lazer", "educacao", "compras", "assinaturas", "viagem", "trabalho", "impostos", "outros", "salario", "vendas", "freelance", "reembolso", "investimentos"]}, "forma_pagamento": {"type": ["string", "null"]}, "ignorar": {"type": "boolean"}, "motivo": {"type": ["string", "null"]}}}}}};
if (a.kind !== 'pdf' && a.kind !== 'texto') return [{ json: { pular: true, kind: a.kind, motivo: a.motivo || a.kind } }];
const conteudo = a.kind === 'pdf'
  ? [{ type: 'file', file: { filename: a.nome || 'extrato.pdf', file_data: 'data:application/pdf;base64,' + a.base64 } }, { type: 'text', text: 'Leia o documento anexado (' + a.nome + ') e devolva todos os lançamentos.' }]
  : 'Arquivo: ' + a.nome + '

CONTEÚDO DO ARQUIVO:
' + a.texto;
return [{ json: { pular: false, tarefa: 'documento', origem: 'extrato', autor: p.autor || null, sistema: regras, mensagens: [{ role: 'user', content: conteudo }], esquema: { name: 'extrato', schema }, max_tokens: 24000 } }];

const m = $('Montar pedido IA').first().json;
let obj = null, erro = null, ia = null;
if (m.pular) erro = m.kind === 'desconhecido' ? 'formato' : (m.motivo === 'download' ? 'download' : 'formato');
else {
  const r = $input.first().json || {};
  ia = r.provedor ? r.provedor + (r.reserva ? ' (reserva)' : '') + (r.modelo ? ' ' + r.modelo : '') : null;
  if (r.ok && r.json && typeof r.json === 'object') obj = r.json;
  else if (r.ok && r.texto) { try { obj = JSON.parse(r.texto); } catch (e) { obj = null; } }
  else if (Array.isArray(r.choices)) { try { obj = JSON.parse(r.choices[0].message.content); } catch (e) { obj = null; } }
  if (!obj) erro = 'leitura';
}
const lanc = obj && Array.isArray(obj.lancamentos) ? obj.lancamentos.filter(l => l && /^\d{4}-\d{2}-\d{2}$/.test(String(l.data)) && Number(l.valor) > 0).slice(0, 500) : [];
const datas = lanc.map(l => l.data).sort();
const ini = datas.length ? DateTime.fromISO(datas[0]).minus({ days: 3 }).toISO() : DateTime.now().minus({ days: 1 }).toISO();
return [{ json: { erro, ia, doc: obj ? { tipo: obj.tipo_documento, instituicao: obj.instituicao, de: obj.periodo_inicio, ate: obj.periodo_fim } : null, lanc, ini } }];

const p = $('Preparar').first().json;
const L = $('Interpretar leitura').first().json;
const NL = String.fromCharCode(10);
const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const dbr = s => String(s || '').slice(8, 10) + '/' + String(s || '').slice(5, 7);
const NOMECAT = { alimentacao: 'Alimentação', educacao: 'Educação', saude: 'Saúde', combustivel: 'Combustível', salario: 'Salário' };
const cat = c => NOMECAT[c] || (String(c || 'outros').charAt(0).toUpperCase() + String(c || 'outros').slice(1));
const fim = (txt, salvar, itens, resumo) => [{ json: { salvar, texto: String.fromCharCode(8203) + txt, itens: itens || [], resumo: resumo || {} } }];
if (L.erro) {
  const msg = L.erro === 'formato'
    ? 'Não consegui abrir esse tipo de arquivo. Mande o extrato ou a fatura em *PDF*, *CSV*, *OFX* ou *Excel* com a legenda *extrato*.'
    : L.erro === 'download' ? 'Não consegui baixar o arquivo. Pode mandar de novo?' : 'Tive um problema para ler esse extrato. Tenta mandar de novo (de preferência em PDF ou CSV)?';
  return fim('📄 ' + p.primeiro + ', ' + msg.charAt(0).toLowerCase() + msg.slice(1), false);
}
if (!L.doc || L.doc.tipo === 'outro' || !L.lanc.length) return fim('📄 ' + p.primeiro + ', esse arquivo não parece um extrato de conta nem uma fatura de cartão, então não importei nada. Se for um comprovante, é só mandar sem a legenda *extrato*.', false);
const exist = $('Lançamentos existentes').all().map(i => i.json).filter(r => r && r.id != null && (r.autor || 'Daniel') === p.autor)
  .map(r => ({ v: Number(r.valor) || 0, tipo: r.tipo === 'receita' ? 'receita' : 'despesa', d: DateTime.fromISO(String(r.data)).setZone('America/Sao_Paulo'), usado: false }));
const ignorados = [], dup = [], novos = [];
for (const l of L.lanc) {
  if (l.ignorar) { ignorados.push(l); continue; }
  const d = DateTime.fromISO(l.data, { zone: 'America/Sao_Paulo' });
  const m = exist.find(e => !e.usado && e.tipo === l.movimento && Math.abs(e.v - Number(l.valor)) < 0.011 && e.d.isValid && Math.abs(e.d.diff(d, 'days').days) <= 2.5);
  if (m) { m.usado = true; dup.push(l); continue; }
  novos.push(l);
}
const gastos = novos.filter(l => l.movimento === 'despesa');
const entradas = novos.filter(l => l.movimento === 'receita');
const soma = a => a.reduce((s, l) => s + Number(l.valor), 0);
const porCat = {};
gastos.forEach(l => { porCat[l.categoria] = (porCat[l.categoria] || 0) + Number(l.valor); });
const topCat = Object.entries(porCat).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([c, v]) => cat(c) + ' ' + brl(v)).join(' · ');
const maiores = gastos.slice().sort((a, b) => b.valor - a.valor).slice(0, 5).map(l => '• ' + dbr(l.data) + ' ' + String(l.descricao).slice(0, 40) + ' — ' + brl(l.valor)).join(NL);
const titulo = (L.doc.tipo === 'fatura_cartao' ? 'Fatura do cartão' : 'Extrato da conta') + (L.doc.instituicao ? ' ' + L.doc.instituicao : '') + (L.doc.de && L.doc.ate ? ' (' + dbr(L.doc.de) + ' a ' + dbr(L.doc.ate) + ')' : '');
const linhas = ['📄 *' + titulo + '*', '', 'Encontrei *' + L.lanc.length + ' lançamentos*:'];
linhas.push('• ' + novos.length + (novos.length === 1 ? ' novo' : ' novos') + (novos.length ? ': ' + brl(soma(gastos)) + ' em gastos' + (entradas.length ? ' e ' + brl(soma(entradas)) + ' em entradas' : '') : ''));
if (dup.length) linhas.push('• ' + dup.length + ' já estavam no Dyno (não vou duplicar)');
if (ignorados.length) linhas.push('• ' + ignorados.length + ' ignorados (pagamento de fatura, saldos, transferências entre suas contas ou investimentos)');
if (!novos.length) { linhas.push('', 'Tudo desse arquivo já está no Dyno, não há nada novo para importar ✅'); return fim(linhas.join(NL), false); }
if (topCat) linhas.push('', '*Por categoria:* ' + topCat);
if (maiores) linhas.push('', '*Maiores gastos:*', maiores);
linhas.push('', 'Responda *IMPORTAR* para salvar os ' + novos.length + ' novos, ou *NÃO IMPORTAR* para descartar.');
const itens = novos.map(l => ({ tipo: l.movimento, valor: Math.round(Number(l.valor) * 100) / 100, categoria: l.categoria, descricao: String(l.descricao).slice(0, 120), data: DateTime.fromISO(l.data + 'T12:00:00', { zone: 'America/Sao_Paulo' }).toUTC().toISO(), forma_pagamento: String(l.forma_pagamento || (L.doc.tipo === 'fatura_cartao' ? 'cartão de crédito' : '')).slice(0, 40) }));
return fim(linhas.join(NL), true, itens, { titulo, novos: novos.length, gastos: Math.round(soma(gastos) * 100) / 100, entradas: Math.round(soma(entradas) * 100) / 100 });

const p = $('Preparar').first().json;
const r = $input.first().json || {};
if (!r.ok || r.acao !== 'confirmar') return [];
return (Array.isArray(r.itens) ? r.itens : []).map(i => ({ json: { tipo: i.tipo, valor: i.valor, categoria: i.categoria, descricao: i.descricao, data: i.data, forma_pagamento: i.forma_pagamento || '', autor: p.autor, comprovante_url: '' } }));

const p = $('Preparar').first().json;
const r = $('Supabase: decidir').first().json || {};
const ZW = String.fromCharCode(8203);
const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
let n = 0;
try { n = $('Gravar lançamentos').all().filter(i => i.json && i.json.id != null).length; } catch (e) { n = 0; }
let texto;
if (!r.ok) texto = p.primeiro + ', não tenho nenhum extrato aguardando confirmação. Para importar, me mande o arquivo (PDF, CSV, OFX ou Excel) com a legenda *extrato*.';
else if (r.acao !== 'confirmar') texto = 'Tudo bem, ' + p.primeiro + '! Descartei a importação, nada foi salvo.';
else { const s = r.resumo || {}; texto = '✅ Pronto, ' + p.primeiro + '! Importei *' + n + ' lançamentos*' + (s.gastos ? ': ' + brl(s.gastos) + ' em gastos' + (s.entradas ? ' e ' + brl(s.entradas) + ' em entradas' : '') : '') + '. Já aparecem no painel, no Extrato do site e nos relatórios.'; }
return [{ json: { corpo: { number: p.numero, text: ZW + texto, delay: 600 } } }];
